from __future__ import annotations

import re
from dataclasses import dataclass


_IDENTIFIERS = r"[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*"
_VERSION_RE = re.compile(
    rf"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    rf"(?:-({_IDENTIFIERS}))?"
    rf"(?:\+({_IDENTIFIERS}))?"
)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise TypeError("version must be a string")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid semantic version: {text!r}")

    prerelease = tuple(match.group(4).split(".")) if match.group(4) else ()
    for identifier in prerelease:
        if (
            _is_numeric_identifier(identifier)
            and len(identifier) > 1
            and identifier[0] == "0"
        ):
            raise ValueError(
                f"numeric pre-release identifier has a leading zero: {identifier!r}"
            )

    build = tuple(match.group(5).split(".")) if match.group(5) else ()
    return Version(
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
        prerelease,
        build,
    )


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _coerce(a)
    right = _coerce(b)

    for attribute in ("major", "minor", "patch"):
        left_part = getattr(left, attribute)
        right_part = getattr(right, attribute)
        if left_part != right_part:
            return -1 if left_part < right_part else 1

    return _compare_prerelease(left.prerelease, right.prerelease)


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _coerce(version)
    if not isinstance(range_, str):
        raise TypeError("range must be a string")

    sets = [_parse_comparator_set(part) for part in range_.split("||")]
    return any(_satisfies_set(candidate, comparator_set) for comparator_set in sets)


def _is_numeric_identifier(identifier: str) -> bool:
    return identifier.isascii() and identifier.isdigit()


def _coerce(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    if isinstance(value, str):
        return parse(value)
    raise TypeError("version must be a string or Version")


def _compare_prerelease(
    left: tuple[str, ...], right: tuple[str, ...]
) -> int:
    if not left and not right:
        return 0
    if not left:
        return 1
    if not right:
        return -1

    for left_id, right_id in zip(left, right):
        left_numeric = _is_numeric_identifier(left_id)
        right_numeric = _is_numeric_identifier(right_id)
        if left_numeric and right_numeric:
            result = _compare_numeric_identifiers(left_id, right_id)
        elif left_numeric:
            result = -1
        elif right_numeric:
            result = 1
        else:
            result = (left_id > right_id) - (left_id < right_id)
        if result:
            return result

    return (len(left) > len(right)) - (len(left) < len(right))


def _compare_numeric_identifiers(left: str, right: str) -> int:
    # Avoid converting arbitrarily long identifiers to int. Leading zeros are
    # impossible after parsing, but normalising keeps hand-built Versions sane.
    left = left.lstrip("0") or "0"
    right = right.lstrip("0") or "0"
    if len(left) != len(right):
        return -1 if len(left) < len(right) else 1
    return (left > right) - (left < right)


def _parse_comparator_set(text: str) -> list[tuple[str, Version]]:
    tokens = text.split()
    if not tokens:
        raise ValueError("empty comparator set")

    comparators = []
    for token in tokens:
        for operator in (">=", "<=", ">", "<", "=", "^", "~"):
            if token.startswith(operator):
                version_text = token[len(operator) :]
                break
        else:
            operator = "="
            version_text = token

        if not version_text:
            raise ValueError(f"invalid comparator: {token!r}")
        comparators.append((operator, parse(version_text)))

    return comparators


