        for _, comparator_version in comparators
    ):
        return False

    return all(
        _satisfies_comparator(version, operator, comparator_version)
        for operator, comparator_version in comparators
    )


def _satisfies_comparator(
    version: Version, operator: str, comparator_version: Version
) -> bool:
    if operator == "=":
        return compare(version, comparator_version) == 0
    if operator == ">":
        return compare(version, comparator_version) > 0
    if operator == ">=":
        return compare(version, comparator_version) >= 0
    if operator == "<":
        return compare(version, comparator_version) < 0
    if operator == "<=":
        return compare(version, comparator_version) <= 0
    if operator == "^":
        return (
            compare(version, comparator_version) >= 0
            and compare(version, _caret_upper_bound(comparator_version)) < 0
        )
    if operator == "~":
        return (
            compare(version, comparator_version) >= 0
            and compare(version, _tilde_upper_bound(comparator_version)) < 0
        )
    raise ValueError(f"invalid comparator operator: {operator!r}")


def _caret_upper_bound(version: Version) -> Version:
    if version.major:
        return Version(version.major + 1, 0, 0)
    if version.minor:
        return Version(0, version.minor + 1, 0)
    return Version(0, 0, version.patch + 1)


def _tilde_upper_bound(version: Version) -> Version:
    return Version(version.major, version.minor + 1, 0)

