def _is_numeric_identifier(identifier: str) -> bool:
    return identifier.isascii() and identifier.isdigit()


def _parse_numeric_part(text: str) -> int:
    # Build the integer in small chunks so arbitrarily long numeric parts do
    # not hit Python's limit on converting long decimal strings to int.
    value = 0
    for start in range(0, len(text), 9):
        chunk = text[start : start + 9]
        value = value * 10 ** len(chunk) + int(chunk)
    return value
